first(){ python3 -I -c '
import json,sys
for l in open(sys.argv[1]):
  try: d=json.loads(l)
  except: continue
  if d.get("type")=="user" and isinstance(d.get("message",{}).get("content"),str) and not d["message"]["content"].startswith("<"):
    print(d["message"]["content"][:160].replace("\n"," ")); break' "$1"; }
P=~/.claude/projects/-Users-konradtabay-Downloads-Primary; for s in 1f2db246-3286-4d93-9d05-c7ff67bac5c9 ce6ca106-7adc-42d7-a7fb-7bf8d3f1dab3 72ff0de6-916d-402f-acfd-f5f3e84f3d0f 7dee52d6-d626-45d1-99f9-b3f79ff6f9a8 5d7cf1cc-d414-48a1-a079-42468b794980; do echo "$s: $(first $P/$s.jsonl)"; done; L=~/.claude/projects/-Users-konradtabay-LouVoice; for f in $L/*.jsonl; do echo "LV $(basename $f): $(first $f)"; done; ls ~/LouVoice

